import numpy as np
import sys

sys.path.append('storage/cognito')

try:
    from hybrid_synthesis_v3_fix import run_hybrid_synthesis_ablation, N_CIRCLES
except ImportError:
    print("CRITICAL ERROR: Could not import hybrid_synthesis_v3_fix.py.")
    def run_hybrid_synthesis_ablation(b): return None, None
    N_CIRCLES = 32

def construct_packing() -> tuple:
    n = N_CIRCLES
    TIME_BUDGET = 120.0

    centers, radii = run_hybrid_synthesis_ablation(refinement_time_budget=TIME_BUDGET)

    if centers is not None and radii is not None:
      return centers, radii * (1.0 - 1e-5)
    else:
      print("Algorithm execution failed, returning fallback packing.")
      centers = np.array([[0.1 + (i % 6) * 0.15, 0.1 + (i // 6) * 0.15] for i in range(n)])
      radii = np.full(n, 0.05)
      return centers, radii
